package com.example.s7hotspot;
import android.app.*;import android.content.*;import android.net.wifi.*;import android.os.*;import android.bluetooth.*;import android.util.Log;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class HotspotService extends Service {
 private WifiManager.LocalOnlyHotspotReservation reservation;private ServerSocket server;private Thread worker;private volatile boolean running;private String ssid="(starting)",pass="",state="Starting";private final String TAG="S7Hotspot";
 @Override public int onStartCommand(Intent i,int flags,int id){if("STOP".equals(i==null?null:i.getAction())){stopSelf();return START_NOT_STICKY;}foreground();startHotspot();return START_STICKY;}
 private void foreground(){Notification.Builder b=new Notification.Builder(this).setContentTitle("S7 local hotspot").setContentText("Web server port 8080").setSmallIcon(android.R.drawable.stat_sys_wifi);startForeground(17,b.build());}
 private void startHotspot(){WifiManager wm=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);try{wm.startLocalOnlyHotspot(new WifiManager.LocalOnlyHotspotCallback(){@Override public void onStarted(WifiManager.LocalOnlyHotspotReservation r){reservation=r;WifiConfiguration c=r.getWifiConfiguration();ssid=c.SSID;pass=c.preSharedKey;state="Hotspot running";Log.i(TAG,"SSID="+ssid+" PASSWORD="+pass);startServer();}@Override public void onFailed(int reason){state="Hotspot failed, reason="+reason;Log.e(TAG,state);startServer();}@Override public void onStopped(){state="Hotspot stopped";}},new Handler(Looper.getMainLooper()));}catch(Exception e){state="Hotspot error: "+e;Log.e(TAG,state,e);startServer();}}
 private synchronized void startServer(){if(running)return;running=true;worker=new Thread(()->{try{server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress("0.0.0.0",8080));while(running){Socket s=server.accept();new Thread(()->handle(s)).start();}}catch(Exception e){Log.e(TAG,"Server",e);}});worker.start();}
 private void handle(Socket s){try(Socket sock=s){sock.setSoTimeout(5000);BufferedReader br=new BufferedReader(new InputStreamReader(sock.getInputStream(),StandardCharsets.UTF_8));String line=br.readLine();if(line==null)return;while((line=br.readLine())!=null&&!line.isEmpty()){}String path=linePath(line);String body;if(path.equals("/api/status")){body="{\"state\":\""+esc(state)+"\",\"ssid\":\""+esc(ssid)+"\",\"bluetooth\":\""+bt()+"\"}";}else if(path.equals("/api/paired")){body=paired();}else{body="<!doctype html><meta name='viewport' content='width=device-width'><meta charset='utf-8'><title>S7 Manager</title><style>body{font:17px system-ui;max-width:650px;margin:30px auto;padding:15px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eee;padding:14px}</style><h2>S7 Local Hotspot Manager</h2><p>Read-only status. Pairing / A2DP control is not implemented.</p><h3>Status</h3><pre id='s'>Loading...</pre><h3>Paired Bluetooth devices</h3><pre id='p'>Loading...</pre><script>async function load(){for(let [id,url] of [['s','/api/status'],['p','/api/paired']]){try{document.getElementById(id).textContent=JSON.stringify(await(await fetch(url)).json(),null,2)}catch(e){document.getElementById(id).textContent=String(e)}}}load();setInterval(load,5000)</script>";}
 byte[] bytes=body.getBytes(StandardCharsets.UTF_8);String mime=path.startsWith("/api/")?"application/json":"text/html";OutputStream out=sock.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: "+mime+"; charset=utf-8\r\nCache-Control: no-store\r\nContent-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(bytes);out.flush();}catch(Exception e){Log.e(TAG,"HTTP",e);}}
 private String linePath(String l){String[] p=l.split(" ");return p.length>1?p[1]:"/";}private String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ");}
 private String bt(){BluetoothAdapter a=BluetoothAdapter.getDefaultAdapter();return a==null?"unsupported":(a.isEnabled()?"on":"off");}
 private String paired(){try{BluetoothAdapter a=BluetoothAdapter.getDefaultAdapter();if(a==null)return "[]";StringBuilder b=new StringBuilder("[");boolean first=true;for(BluetoothDevice d:a.getBondedDevices()){if(!first)b.append(',');first=false;b.append("{\"name\":\"").append(esc(String.valueOf(d.getName()))).append("\",\"address\":\"").append(esc(d.getAddress())).append("\"}");}return b.append(']').toString();}catch(Exception e){return "{\"error\":\""+esc(e.toString())+"\"}";}}
 @Override public void onDestroy(){running=false;try{if(server!=null)server.close();}catch(Exception ignored){}if(reservation!=null)reservation.close();super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
